def digits(n, b):            # целое n >= 0, целое основание b >= 2
    if n < 0 or b < 2:
        raise ValueError('Нужно n >= 0 и b >= 2')
    if n == 0:
        return [0]
    d = []
    while n > 0:
        d.append(n % b)
        n //= b
    return d[::-1]

best = 0
for x in range(1, 2031):
    v = 7 ** 170 + 7 ** 100 - x
    if digits(v, 7).count(0) == 71:
        best = x                 # наибольшее — не прерываем цикл, запоминаем последнее
print(best)

from string import printable

res = set()
for x in printable[:22]:
    for y in printable[:22]:
        a = int(f'34256{x}4', 22) + int(f'72847{y}3', 22)
        if a % 125 == 0:
            res.add((int(x, 22) + int(y, 22), a // 125))
for total, quotient in sorted(res):
    print(total, quotient)

